<body>

<!-- HEADER -->
<div class="report-header">
  <div class="container">
    <h1>Global Fuel Price Trends & Policy Impact Analysis</h1>
    <p class="subtitle">A comprehensive trend analysis of retail fuel prices across 84 countries, examining the interplay between Brent Crude benchmarks, taxation, subsidies, and regional economic conditions over the 2020–2026 period.</p>
    <div class="meta">
      <span>Coverage: {date_min} – {date_max}</span>
      <span>Countries: {total_countries}</span>
      <span>Data points: {len(df):,}</span>
      <span>Generated: {datetime.now().strftime('%B %d, %Y')}</span>
    </div>
  </div>
</div>

<!-- KPI BAR -->
<div class="kpi-bar">
  <div class="kpi-card">
    <div class="kpi-label">Avg. Retail Petrol Price</div>
