#!/usr/bin/env python3
"""Generate Global Fuel Price Trends & Policy Impact Analysis (2020-2026) report."""

import pandas as pd
import numpy as np
import json
from datetime import datetime

# Load Data
df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['date'])
df['year'] = df['date'].dt.year

print(f"Loaded {len(df):,} rows, {df['country'].nunique()} countries, {df['date'].min().date()} to {df['date'].max().date()}")

# ── SECTION 1: Global Overview ──
total_countries = df['country'].nunique()
date_min = df['date'].min().strftime('%B %d, %Y')
date_max = df['date'].max().strftime('%B %d, %Y')
total_weeks = df['date'].nunique()

overall_stats = {}
for fuel in ['petrol_usd_liter', 'diesel_usd_liter', 'lpg_usd_liter']:
    col = fuel.replace('_usd_liter', '').capitalize()
    overall_stats[col] = {
        'mean': round(df[fuel].mean(), 3),
        'median': round(df[fuel].median(), 3),
        'min': round(df[fuel].min(), 3),
        'max': round(df[fuel].max(), 3),
        'std': round(df[fuel].std(), 3),
    }

brent_stats = {
    'mean': round(df['brent_crude_usd'].mean(), 2),
    'median': round(df['brent_crude_usd'].median(), 2),
    'min': round(df['brent_crude_usd'].min(), 2),
    'max': round(df['brent_crude_usd'].max(), 2),
    'std': round(df['brent_crude_usd'].std(), 2),
}

avg_petrol = round(df['petrol_usd_liter'].mean(), 3)

# ── SECTION 2: Temporal Trends & Volatility ──
yearly = df.groupby('year').agg(
    petrol_mean=('petrol_usd_liter', 'mean'),
    diesel_mean=('diesel_usd_liter', 'mean'),
    lpg_mean=('lpg_usd_liter', 'mean'),
    brent_mean=('brent_crude_usd', 'mean'),
    petrol_std=('petrol_usd_liter', 'std'),
    diesel_std=('diesel_usd_liter', 'std'),
).reset_index().round(3)

brent_weekly = df.drop_duplicates('date')[['date', 'brent_crude_usd']].sort_values('date')
weekly_global = df.groupby('date').agg(
    petrol_mean=('petrol_usd_liter', 'mean'),
    diesel_mean=('diesel_usd_liter', 'mean'),
    lpg_mean=('lpg_usd_liter', 'mean'),
).reset_index().sort_values('date')

merged_weekly = weekly_global.merge(brent_weekly[['date', 'brent_crude_usd']], on='date')
corr_petrol = round(merged_weekly['brent_crude_usd'].corr(merged_weekly['petrol_mean']), 3)
corr_diesel = round(merged_weekly['brent_crude_usd'].corr(merged_weekly['diesel_mean']), 3)
corr_lpg = round(merged_weekly['brent_crude_usd'].corr(merged_weekly['lpg_mean']), 3)

# COVID shock
covid_q1 = df[(df['date'] >= '2020-01-01') & (df['date'] < '2020-04-01')]
covid_q2 = df[(df['date'] >= '2020-04-01') & (df['date'] < '2020-07-01')]
covid_drop_petrol = round(((covid_q2['petrol_usd_liter'].mean() - covid_q1['petrol_usd_liter'].mean()) / covid_q1['petrol_usd_liter'].mean()) * 100, 1)
covid_drop_brent = round(((covid_q2['brent_crude_usd'].mean() - covid_q1['brent_crude_usd'].mean()) / covid_q1['brent_crude_usd'].mean()) * 100, 1)

# 2022 crisis
crisis_h1_2021 = df[(df['date'] >= '2021-01-01') & (df['date'] < '2021-07-01')]
crisis_h1_2022 = df[(df['date'] >= '2022-01-01') & (df['date'] < '2022-07-01')]
crisis_rise_petrol = round(((crisis_h1_2022['petrol_usd_liter'].mean() - crisis_h1_2021['petrol_usd_liter'].mean()) / crisis_h1_2021['petrol_usd_liter'].mean()) * 100, 1)
crisis_rise_brent = round(((crisis_h1_2022['brent_crude_usd'].mean() - crisis_h1_2021['brent_crude_usd'].mean()) / crisis_h1_2021['brent_crude_usd'].mean()) * 100, 1)

# Peak/trough Brent
brent_peak_row = brent_weekly.loc[brent_weekly['brent_crude_usd'].idxmax()]
brent_peak_date = brent_peak_row['date'].strftime('%B %d, %Y')
brent_peak_price = round(brent_peak_row['brent_crude_usd'], 2)
brent_trough_row = brent_weekly.loc[brent_weekly['brent_crude_usd'].idxmin()]
brent_trough_date = brent_trough_row['date'].strftime('%B %d, %Y')
brent_trough_price = round(brent_trough_row['brent_crude_usd'], 2)

# Yearly volatility
yearly_vol = df.groupby('year').agg(
    petrol_cv=('petrol_usd_liter', lambda x: (x.std() / x.mean()) * 100),
    diesel_cv=('diesel_usd_liter', lambda x: (x.std() / x.mean()) * 100),
    brent_cv=('brent_crude_usd', lambda x: (x.std() / x.mean()) * 100),
).reset_index().round(1)

# ── SECTION 3: Regional Comparison ──
region_avg = df.groupby('region').agg(
    petrol_mean=('petrol_usd_liter', 'mean'),
    diesel_mean=('diesel_usd_liter', 'mean'),
    lpg_mean=('lpg_usd_liter', 'mean'),
    country_count=('country', 'nunique'),
).reset_index().round(3).sort_values('petrol_mean', ascending=False)

yearly_region = df.groupby(['year', 'region'])['petrol_usd_liter'].mean().reset_index()
yearly_region_pivot = yearly_region.pivot(index='year', columns='region', values='petrol_usd_liter')
yearly_spread = (yearly_region_pivot.max(axis=1) - yearly_region_pivot.min(axis=1)).round(3)

highest_region = region_avg.iloc[0]['region']
highest_petrol = region_avg.iloc[0]['petrol_mean']
lowest_region = region_avg.iloc[-1]['region']
lowest_petrol = region_avg.iloc[-1]['petrol_mean']

regional_yearly = df.groupby(['year', 'region']).agg(petrol_mean=('petrol_usd_liter', 'mean')).reset_index().round(3)
regional_yearly_list = []
for region in regional_yearly['region'].unique():
    rdf = regional_yearly[regional_yearly['region'] == region].sort_values('year')
    regional_yearly_list.append({
        'region': region,
        'years': [int(y) for y in rdf['year'].tolist()],
        'values': [float(v) for v in rdf['petrol_mean'].tolist()],
    })

# ── SECTION 4: Subsidy & Tax Analysis ──
subsidy_avg = df.groupby('subsidy_level').agg(
    petrol_mean=('petrol_usd_liter', 'mean'),
    diesel_mean=('diesel_usd_liter', 'mean'),
    lpg_mean=('lpg_usd_liter', 'mean'),
    tax_mean=('tax_percentage', 'mean'),
).reset_index().round(3)

high_sub_petrol = float(subsidy_avg[subsidy_avg['subsidy_level'] == 'High']['petrol_mean'].values[0])
low_sub_petrol = float(subsidy_avg[subsidy_avg['subsidy_level'] == 'Low']['petrol_mean'].values[0])
subsidy_dampening = round(((low_sub_petrol - high_sub_petrol) / low_sub_petrol) * 100, 1)

subsidy_income = df.groupby(['subsidy_level', 'income_level']).agg(
    petrol_mean=('petrol_usd_liter', 'mean'),
    diesel_mean=('diesel_usd_liter', 'mean'),
    tax_mean=('tax_percentage', 'mean'),
).reset_index().round(3)

pass_through = {}
for sub_level in ['High', 'Low']:
    sub_df = df[df['subsidy_level'] == sub_level]
    sub_weekly = sub_df.groupby('date').agg(
        petrol_mean=('petrol_usd_liter', 'mean'),
        brent_mean=('brent_crude_usd', 'mean'),
    ).reset_index()
    corr = round(sub_weekly['brent_mean'].corr(sub_weekly['petrol_mean']), 3)
    pass_through[sub_level] = corr

yearly_subsidy = df.groupby(['year', 'subsidy_level']).agg(petrol_mean=('petrol_usd_liter', 'mean')).reset_index().round(3)

tax_by_income = df.groupby('income_level').agg(
    tax_mean=('tax_percentage', 'mean'),
    tax_median=('tax_percentage', 'median'),
    tax_std=('tax_percentage', 'std'),
).reset_index().round(1)

tax_kpi = tax_by_income.set_index('income_level')['tax_mean'].to_dict()
tax_price_corr = round(df['tax_percentage'].corr(df['petrol_usd_liter']), 3)

# ── SECTION 5: Income Level Segmentation ──
income_avg = df.groupby('income_level').agg(
    petrol_mean=('petrol_usd_liter', 'mean'),
    diesel_mean=('diesel_usd_liter', 'mean'),
    lpg_mean=('lpg_usd_liter', 'mean'),
    tax_mean=('tax_percentage', 'mean'),
    petrol_cv=('petrol_usd_liter', lambda x: (x.std() / x.mean()) * 100),
